-- Generated explicit legacy-clock protocol by author_legacy_clock_copy.py.
-- validation_wall_offset is ONLY a zero-shift wall-value validator when unresolved.
-- It is never persisted as a source offset or used to manufacture UTC.
SET @compact_source_clock_unresolved=BINARY '__SOURCE_SDK_OFFSET__'=BINARY 'UNRESOLVED';
SET @compact_validation_wall_offset=IF(@compact_source_clock_unresolved,'+00:00','__SOURCE_SDK_OFFSET__');
CREATE TEMPORARY TABLE compact_sdk_guard(valid INT NOT NULL CHECK(valid=1));
START TRANSACTION;
INSERT INTO compact_sdk_guard SELECT IF(NOT @compact_source_clock_unresolved OR REGEXP_LIKE('__SOURCE_SNAPSHOT_SHA256__','^[a-f0-9]{64}$','c'),1,0);
INSERT INTO compact_sdk_guard SELECT IF(REGEXP_LIKE(@compact_validation_wall_offset,'^[+-][0-9]{2}:[0-9]{2}$','c') AND CONVERT_TZ('2026-01-01',@compact_validation_wall_offset,'+00:00') IS NOT NULL,1,0);
INSERT INTO compact_sdk_guard SELECT NOT EXISTS(SELECT 1 FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state s WHERE (s.updated_at IS NOT NULL AND (CONVERT_TZ(s.updated_at,@compact_validation_wall_offset,'+00:00') IS NULL OR NOT(TIMESTAMPDIFF(MICROSECOND,CONVERT_TZ(s.updated_at,@compact_validation_wall_offset,'+00:00'),s.updated_at)<=>((IF(LEFT(@compact_validation_wall_offset,1)='-',-1,1)*(CAST(SUBSTRING(@compact_validation_wall_offset,2,2) AS SIGNED)*3600+CAST(SUBSTRING(@compact_validation_wall_offset,5,2) AS SIGNED)*60))*1000000)))));
INSERT INTO compact_sdk_guard SELECT IF(COUNT(*)=0,1,0) FROM runtime_state WHERE namespace='SDK_CHECKPOINT';
INSERT INTO compact_sdk_guard SELECT IF(CONVERT_TZ('2026-01-01 00:00:00',@compact_validation_wall_offset,'+00:00') IS NOT NULL,1,0);
INSERT INTO compact_sdk_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_workbench_owner WHERE user_id<=0;
INSERT INTO compact_sdk_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state
 WHERE user_id NOT REGEXP '^[1-9][0-9]{0,18}$' OR CAST(user_id AS DECIMAL(20,0))>9223372036854775807
 OR revision<1 OR JSON_VALID(state_json)=0 OR CONVERT_TZ(updated_at,@compact_validation_wall_offset,'+00:00') IS NULL;
INSERT INTO runtime_state(namespace,owner_id,scope_key,session_id,state_key,revision,state_code,payload_version,payload_json,created_at,updated_at,legacy_clock_json) SELECT 'SDK_CHECKPOINT',CAST(user_id AS SIGNED),SHA2(CONCAT(OCTET_LENGTH(CONVERT(session_id USING utf8mb4)),':',session_id,':',OCTET_LENGTH(CONVERT(state_key USING utf8mb4)),':',state_key),256),session_id,state_key,revision,'LIVE',1,JSON_OBJECT('stateJson',state_json),NULL,IF(@compact_source_clock_unresolved,NULL,CONVERT_TZ(updated_at,@compact_validation_wall_offset,'+00:00')),IF(@compact_source_clock_unresolved,JSON_OBJECT('protocol','doorhandle-legacy-clock-v1','status','UNRESOLVED','sourceTable','agent_workbench_sdk_state','sourceKey',JSON_OBJECT('id',agent_workbench_sdk_state.`id`),'sourceSnapshotSha256','__SOURCE_SNAPSHOT_SHA256__','sourceRowSha256',SHA2(CAST(JSON_OBJECT('id',agent_workbench_sdk_state.`id`,'user_id',agent_workbench_sdk_state.`user_id`,'session_id',agent_workbench_sdk_state.`session_id`,'state_key',agent_workbench_sdk_state.`state_key`,'revision',agent_workbench_sdk_state.`revision`,'state_json',agent_workbench_sdk_state.`state_json`,'updated_at',CAST(agent_workbench_sdk_state.`updated_at` AS CHAR CHARACTER SET utf8mb4)) AS CHAR CHARACTER SET utf8mb4),256),'sourceWallTimes',JSON_OBJECT('updated_at',CAST(agent_workbench_sdk_state.`updated_at` AS CHAR))),NULL) FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state ORDER BY id;
INSERT INTO runtime_state(namespace,owner_id,scope_key,revision,created_at,legacy_clock_json) SELECT 'WORKBENCH',user_id,'',0,NULL,NULL FROM `__SOURCE_SCHEMA__`.agent_workbench_owner
 ON DUPLICATE KEY UPDATE namespace=runtime_state.namespace;
INSERT INTO compact_sdk_guard SELECT IF(
 (SELECT COUNT(*) FROM runtime_state WHERE namespace='SDK_CHECKPOINT')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state),1,0);
INSERT INTO compact_sdk_guard SELECT IF(COUNT(*)=0,1,0)
 FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state s LEFT JOIN runtime_state r
 ON r.namespace='SDK_CHECKPOINT' AND r.owner_id=CAST(s.user_id AS SIGNED) AND BINARY r.session_id=BINARY s.session_id AND BINARY r.state_key=BINARY s.state_key
 WHERE r.owner_id IS NULL OR r.revision<>s.revision OR NOT (BINARY JSON_UNQUOTE(JSON_EXTRACT(r.payload_json,'$.stateJson'))<=>BINARY s.state_json)
 OR BINARY r.scope_key<>BINARY SHA2(CONCAT(OCTET_LENGTH(CONVERT(s.session_id USING utf8mb4)),':',s.session_id,':',OCTET_LENGTH(CONVERT(s.state_key USING utf8mb4)),':',s.state_key),256)
 OR NOT(r.updated_at<=>IF(@compact_source_clock_unresolved,NULL,CONVERT_TZ(s.updated_at,@compact_validation_wall_offset,'+00:00')));
INSERT INTO compact_sdk_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_workbench_sdk_state LEFT JOIN runtime_state clock_target ON BINARY clock_target.`namespace`<=>BINARY 'SDK_CHECKPOINT' AND BINARY clock_target.`owner_id`<=>BINARY CAST(user_id AS SIGNED) AND BINARY clock_target.`scope_key`<=>BINARY SHA2(CONCAT(OCTET_LENGTH(CONVERT(session_id USING utf8mb4)),':',session_id,':',OCTET_LENGTH(CONVERT(state_key USING utf8mb4)),':',state_key),256) WHERE (clock_target.namespace IS NULL OR NOT(clock_target.legacy_clock_json<=>IF(@compact_source_clock_unresolved,JSON_OBJECT('protocol','doorhandle-legacy-clock-v1','status','UNRESOLVED','sourceTable','agent_workbench_sdk_state','sourceKey',JSON_OBJECT('id',agent_workbench_sdk_state.`id`),'sourceSnapshotSha256','__SOURCE_SNAPSHOT_SHA256__','sourceRowSha256',SHA2(CAST(JSON_OBJECT('id',agent_workbench_sdk_state.`id`,'user_id',agent_workbench_sdk_state.`user_id`,'session_id',agent_workbench_sdk_state.`session_id`,'state_key',agent_workbench_sdk_state.`state_key`,'revision',agent_workbench_sdk_state.`revision`,'state_json',agent_workbench_sdk_state.`state_json`,'updated_at',CAST(agent_workbench_sdk_state.`updated_at` AS CHAR CHARACTER SET utf8mb4)) AS CHAR CHARACTER SET utf8mb4),256),'sourceWallTimes',JSON_OBJECT('updated_at',CAST(agent_workbench_sdk_state.`updated_at` AS CHAR))),NULL)) OR NOT(BINARY clock_target.`payload_json`<=>BINARY JSON_OBJECT('stateJson',state_json)) OR NOT(clock_target.`created_at`<=>NULL) OR NOT(clock_target.`updated_at`<=>IF(@compact_source_clock_unresolved,NULL,CONVERT_TZ(updated_at,@compact_validation_wall_offset,'+00:00'))));
COMMIT;
DROP TEMPORARY TABLE compact_sdk_guard;
